"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["33118"],{30099(e){e.exports=JSON.parse('{"id":"FIN-1156","slug":"anchoring-bias","term":"Anchoring Bias","also_known_as":[],"difficulty":"Intermediate","definition":"Anchoring bias is the tendency to rely too heavily on the first piece of information encountered, called the anchor, when making judgments and decisions, even when it is not relevant.","explanation":["People often use an initial number as a reference point and adjust from it, but usually not enough. Psychologists Amos Tversky and Daniel Kahneman showed this effect in experiments where even random numbers influenced people\'s estimates.","In investing, a common anchor is the price paid for a share. An investor who bought at 50 may refuse to sell while it trades at 35, waiting for it to get back to 50, even though the purchase price has no bearing on the company\'s future prospects.","Other anchors include a share\'s recent high, an analyst\'s first price target or the asking price of a house. In negotiations, the first offer often acts as an anchor that shapes the final outcome.","Anchoring can lead investors to hold losing positions, misjudge value and underreact to new information. Reducing its effect involves asking what an investment is worth based on current information, considering a range of possible values and asking whether one would buy the investment today at the current price."],"note":"","total":1500,"prev":{"slug":"amortization-schedule","term":"Amortization Schedule"},"next":{"slug":"angel-investor","term":"Angel Investor"}}')}}]);